// Public FAQ — 120 questions in seven topics. Product answers are written from the code, Terms and live rules
// (numbers come from publicFacts(), so they follow Admin → Rules & Settings). Edit here; pages update on deploy.
import type { PublicFacts } from "@/lib/public/facts";
import { usd } from "@/lib/public/facts";
import { ROUTES, SUPPORT_EMAIL } from "@/lib/public/site";

export type Faq = { id: string; q: string; a: string[]; tips?: string[]; link?: { href: string; label: string } };
export type FaqCategory = { slug: string; title: string; audience: string; intro: string; items: Faq[] };

const G = (slug: string, label: string) => ({ href: `/resources/${slug}`, label });
const P = (href: string, label: string) => ({ href, label });

export function faqCategories(f: PublicFacts): FaqCategory[] {
  const fee = usd(f.feeDollars), cap = usd(f.capDollars);
  return [
    {
      slug: "business-discovery", title: "Business discovery and free listings", audience: "Beauty and wellness professionals",
      intro: "Where to list your services, how listings differ from booking tools, and how to be easier to find.",
      items: [
        { id: "where-list-free", q: "Where can I list my beauty business for free?", a: [`If students are part of your clientele, list on Nearest: new professionals list free, with no monthly fee, and verified students in your city can find you and request appointments. Pair it with a free Google Business Profile so people searching nearby find you too, and one social profile with your booking link. Read what any listing charges per booking — on Nearest it's a ${fee} booking fee added to the student's total by default.`], tips: ["Use the same business name, area and services everywhere.", "Two or three well-kept listings beat ten forgotten ones."], link: G("where-to-list-beauty-business-free", "Where to list your beauty business for free") },
        { id: "free-advertising", q: "What are the best free ways to advertise a beauty business?", a: ["Get in front of people who are already looking: a free listing where clients choose professionals, referrals from happy clients, a complete Google Business Profile, and short videos of real results. For student clients, a free Nearest profile puts your prices and work in front of verified students in your city without paying for ads. Consistency beats volume — three posts a week for three months does more than thirty in one week."], link: G("get-more-beauty-clients-without-ads", "How to get more beauty clients without ads") },
        { id: "nail-discovered", q: "How do I get my nail business discovered online?", a: ["Make it easy for someone looking for nails to see your work, your prices and how to book. Post clear photos of finished sets with the shape, length and style named, list your prices, and keep one booking link everywhere. A Nearest profile lets verified students in your city browse your sets and request a time — free for new professionals."], tips: ["Name styles the way clients search: \"short almond French tips\", not \"new set\".", "Ask every happy client for a review the same day."], link: G("nail-tech-30-day-content-calendar", "30-day content calendar for nail techs") },
        { id: "hairstylist-no-ads", q: "How can hairstylists find new clients without paid ads?", a: ["Lean on people who've seen your work and on places where clients already choose a stylist. Ask each client for one referral, post before-and-afters with the service and length named, keep a waitlist, and list on Nearest so verified students nearby can find you. Model Calls on Nearest let you fill practice appointments while you build your portfolio."], link: G("first-10-clients-new-hairstylist", "Your first 10 clients as a new stylist") },
        { id: "lash-list", q: "Where can independent lash technicians list their services?", a: ["Use a listing where clients can see your sets, prices and refill policy and book without a DM. Nearest gives lash techs a free profile in front of verified students in their city, with booking, deposits and reminders handled in the app, and it works alongside the booking tool you use for other clients. Show healed results and aftercare wherever you post."], link: G("more-lash-clients-without-discounting", "More lash clients without discounting") },
        { id: "braiding-no-monthly", q: "Can I list my braiding business without paying monthly fees?", a: [`Yes. On Nearest, new professionals list free with no monthly membership fee. A ${fee} booking fee is added to each booking by default, so students see one total and you keep your full price; card processing is deducted from your payout. List your sizes, lengths and whether hair is included so students can compare.`], link: P("/for-professionals#fees", "How Nearest's fees work") },
        { id: "what-directory", q: "What is a beauty business directory?", a: ["A searchable list of professionals with their services, location, photos and a way to contact or book. General directories list everyone for everyone. Nearest is built for one audience — verified students — so your profile is shown to students in your city looking for student-friendly prices, and they can book and pay inside the app."], link: P("/free-business-listing", "Free listings, compared") },
        { id: "listing-vs-booking", q: "How is a business listing different from a booking platform?", a: ["A listing helps people find you; a booking platform runs the appointment — calendar, deposits, reminders and payment. Nearest does both for student clients: students find you, request a time, and pay through the app once you accept. You can keep your existing booking tool for everyone else."], link: G("where-to-list-beauty-business-free", "Where to list your business") },
        { id: "multiple-platforms", q: "Can I use multiple booking platforms at the same time?", a: ["Yes, as long as you protect yourself from double bookings. Keep your hours the same everywhere and block time as soon as a booking comes in. Nearest is designed to sit alongside your current tool: student bookings come through Nearest, everyone else books the way they do now."], tips: ["Turn on Nearest's phone alerts so new requests reach you instantly."], link: P("/faq#nearest-alongside", "Using Nearest alongside another app") },
        { id: "easier-google", q: "How do I make my beauty services easier to find on Google?", a: ["Claim your Google Business Profile, choose accurate categories, add services with prices, post photos and ask for reviews that name the service. Set a service area if you work from home. Your Nearest booking link (usenearest.com/pro-yourname) works as the booking link on your Google profile."], link: G("get-beauty-business-found-on-google", "Get your beauty business found on Google") },
        { id: "home-based-safely", q: "How do I promote a home-based beauty business safely?", a: ["Promote your work, not your address. Show your area publicly, share the exact address only with confirmed clients, take deposits and keep messages in your booking tool. Nearest does this for you: your street address is shared only with a booked client on the appointment day, phone numbers and emails aren't shared, and every booking includes a protected deposit."], tips: ["Check local zoning and licensing rules for home-based services.", "You can decline any request."], link: P("/for-professionals#how-booking-works", "How bookings work on Nearest") },
        { id: "profile-info", q: "What information should I include in a beauty professional profile?", a: ["A clear photo of you, your business name, each service with price and duration, your area, your hours, real photos of your work, and your policies. A short bio saying who you love working with helps the right clients pick you. A Nearest profile has a place for each of these, plus add-ons, a portfolio you can tag by service, and reviews from completed appointments."], link: G("improve-beauty-profile-booking-conversion", "Profile and booking conversion checklist") },
        { id: "need-website", q: "Do I need a website to market my beauty services?", a: ["Not to get started. A bookable profile and an active social account can carry a new business. Every Nearest professional gets a public booking page at usenearest.com/pro-yourname with services, prices and portfolio — many professionals use it as their website link. A website of your own can come later."], link: P("/for-professionals", "Nearest for professionals") },
        { id: "no-followers", q: "How do I promote my beauty business when I have no followers?", a: ["Followers come after bookings, not before. Post real work, share it where local people already are, and ask first clients to tag you. A listing doesn't depend on followers: on Nearest, verified students browsing your city see your profile whether you have 50 followers or 50,000."], link: G("get-more-beauty-clients-without-ads", "Getting clients without ads") },
        { id: "not-in-search", q: "What can I do if my beauty business is not appearing in search results?", a: ["Check that your Google Business Profile is verified, your category and service area are right, and your details match everywhere. Add services, photos and reviews, and give it a few weeks — no one can guarantee search placement. Meanwhile, a Nearest profile puts you in front of students in your city without waiting for search rankings."], link: G("get-beauty-business-found-on-google", "Diagnose search visibility") },
      ],
    },
    {
      slug: "getting-clients", title: "Getting clients and improving bookings", audience: "Beauty and wellness professionals",
      intro: "Practical steps to fill your schedule, turn interest into bookings and keep clients coming back.",
      items: [
        { id: "first-10", q: "How do I get my first 10 beauty clients?", a: ["Tell people who already trust you, with one clear service and price. Offer a few model appointments in exchange for photos and reviews, post every result, and ask each client for one referral. Listing on Nearest adds students in your city who are actively looking — and you can post Model Calls there to fill practice slots."], link: G("first-10-clients-new-hairstylist", "Your first 10 clients, step by step") },
        { id: "nail-more", q: "How can a nail tech get more bookings?", a: ["Make your best-selling sets easy to book: show them with names and prices, promote specific openings, and rebook at checkout. Students book nails before school events and breaks — a Nearest profile with clear prices and after-school hours puts you in front of them, free for new professionals."], link: G("nail-tech-30-day-content-calendar", "30-day nail tech content calendar") },
        { id: "new-stylist", q: "How can a new hairstylist build clientele?", a: ["Pick two or three signature services, price them clearly, build a portfolio with model appointments, and rebook every client before they leave. Students are a strong first clientele — they book regularly and refer friends. On Nearest you can list your services and post Model Calls to verified students in your city."], link: G("first-10-clients-new-hairstylist", "Building clientele as a new stylist") },
        { id: "barber-regulars", q: "How can a barber attract regular clients?", a: ["Regulars come from reliability: consistent hours, on-time starts, remembering how each client likes their cut, and booking the next visit before they leave. Students need cuts every few weeks; on Nearest they can find your cuts and prices and request a time, and you can set after-school hours."], link: G("get-more-beauty-clients-without-ads", "Growing without paid ads") },
        { id: "makeup-more", q: "How can a makeup artist book more appointments?", a: ["Market ahead of event seasons — prom, homecoming, graduation — with clear packages, trials and travel details. Show looks on different skin tones. On Nearest, students compare makeup artists by price and portfolio and can add extras to a base service; you can also add a travel fee when you go to them."], link: G("student-clients-prom-homecoming-graduation", "Marketing event-season appointments") },
        { id: "lash-empty", q: "How can a lash tech fill empty appointment slots?", a: ["Message your waitlist first, post specific openings, offer fills to clients who are due, and use deposits to discourage last-minute cancellations. Instead of discounting, add a steady source of new clients: on Nearest, verified students in your city can request your open times."], link: G("more-lash-clients-without-discounting", "More lash clients without discounting") },
        { id: "braider-repeat", q: "How can a braider attract repeat clients?", a: ["Make the next appointment part of the service: say how long the style should last, book the takedown or reinstall before they leave, and share aftercare that protects edges and scalp. Students reinstall on a school-year rhythm, which makes them loyal braid clients — Nearest lets them find and rebook you easily."], link: G("repeat-clients-braiding-locs", "Repeat clients for braiding and locs") },
        { id: "followers-to-bookings", q: "How do I turn social media followers into bookings?", a: ["Give followers one easy way to book: pin a post with services and prices, end posts with a single next step, and share specific openings. Your Nearest link (usenearest.com/pro-yourname) works in any bio — students tap it, see your prices and request a time without a DM."], link: G("improve-beauty-profile-booking-conversion", "Turn views into bookings") },
        { id: "views-no-book", q: "Why do people view my beauty page but not book?", a: ["Usually something is missing or unclear: no prices, unclear location, no open times, too many steps, or photos that don't match the service. A Nearest profile shows prices, durations, open times and a request button on every service, which removes most of that friction for student clients."], link: G("why-beauty-business-not-getting-bookings", "Diagnostic checklist") },
        { id: "slow", q: "What should I do when my beauty business is slow?", a: ["Use slow weeks to build demand: message clients who are due, post every day, ask for reviews, refresh your photos and fix friction on your booking page. Add a new source of clients rather than a permanent price cut — a free Nearest listing puts you in front of students in your city."], link: G("why-beauty-business-not-getting-bookings", "What to check when bookings slow down") },
        { id: "no-shows", q: "How can I reduce no-shows and last-minute cancellations?", a: ["Take a deposit, send reminders, and make your policy short and visible before booking. On Nearest, students pay in full to confirm, reminders go out automatically, and every booking includes a protected deposit that's paid to you on a late cancellation or no-show."], link: P("/faq#cancellations-refunds", "How Nearest handles cancellations") },
        { id: "rebook", q: "How do I encourage clients to rebook?", a: ["Ask before they leave and suggest a date that fits the service cycle — \"your fill is due in about three weeks, does the 14th work?\" Explain why timing matters and send a reminder when they're due. On Nearest, students can save you as a favorite and rebook from your profile in a few taps."], link: G("repeat-clients-braiding-locs", "Building repeat clients") },
        { id: "referrals", q: "How can I ask customers for referrals without sounding pushy?", a: ["Ask right after the client sees the result, and make it simple: \"If a friend asks who did your hair, I'd love for you to send them my way.\" Give them something easy to share — your Nearest link works well, because friends can see your prices and book directly."], link: P("/beauty-marketing-resources#referral-scripts", "Referral scripts you can copy") },
        { id: "stand-out", q: "How do I stand out in a saturated beauty market?", a: ["Be specific about what you're known for and say it in your bio, photos and services. Reliability and clear communication set you apart too. Nearest limits each service category to a few professionals per city — five at first — so you're never one of fifty in your category."], link: G("improve-beauty-profile-booking-conversion", "Make your profile stand out") },
        { id: "trust-new", q: "How do I build trust as a new beauty professional?", a: ["Show real work, list prices and policies, state your training or license status honestly, keep your space visibly clean and collect reviews. On Nearest your identity is verified, you choose your professional status, and reviews come only from students who completed an appointment with you."], link: G("first-10-clients-new-hairstylist", "Building trust from day one") },
        { id: "booking-info", q: "What booking information do clients need before scheduling?", a: ["The service, price, duration, location, how to prepare, your deposit and cancellation policy, and your open times. On Nearest each of these is part of your profile and the booking flow, so students have what they need before they request."], link: G("improve-beauty-profile-booking-conversion", "Booking-page checklist") },
        { id: "weekday-slots", q: "How do I fill weekday or after-school appointment slots?", a: ["Promote them to people who can use them — students after classes especially. Name the times in your posts, create a quicker service that fits a short window, and offer those times to clients who are due. On Nearest you can set after-school hours separately from your regular hours so students see them."], link: G("student-clients-prom-homecoming-graduation", "Attracting student clients") },
      ],
    },
    {
      slug: "marketing", title: "Marketing and content creation", audience: "Beauty and wellness professionals",
      intro: "Content plans, captions, flyers and seasonal promotions that bring bookings.",
      items: [
        { id: "content-calendar", q: "How do I create a 30-day beauty content calendar?", a: ["Pick four or five content types — results, process, tips, trust and booking posts — and rotate them through the month, three to five posts a week. Batch-film on a slow day. Make every booking post point to one link; your Nearest link lets students request you directly."], link: G("nail-tech-30-day-content-calendar", "A full 30-day calendar you can copy") },
        { id: "nail-instagram", q: "What should nail techs post on Instagram?", a: ["Clear photos and short videos of finished sets, the process, close-ups of clean cuticle work, repairs, and your price list with a booking link. Name shape, length and style. Add posts aimed at students — event sets and after-school times — and link your Nearest profile."], link: G("nail-tech-30-day-content-calendar", "30 days of nail content ideas") },
        { id: "hair-tiktok", q: "What should hairstylists post on TikTok?", a: ["Short transformations, the one step that makes a style work, honest timing, maintenance tips and answers to client questions. Talk to the camera — people book people. End with where to book; a Nearest link lets students who find you on TikTok request a time."], link: G("first-10-clients-new-hairstylist", "Getting clients as a stylist") },
        { id: "content-bookings", q: "What content helps beauty businesses get bookings?", a: ["Content that answers what a client wonders right before booking: will it suit me, how much is it, how long does it take, can I trust you, how do I book? Results with prices, process clips, reviews and specific openings convert best — especially when they link to a profile students can book from, like your Nearest page."], link: G("improve-beauty-profile-booking-conversion", "Content that converts") },
        { id: "flyer-create", q: "How do I create a flyer for my beauty business?", a: ["One message, one standout photo, two to four priced services, your area and one way to book — a QR code. Point the QR code at a page where people can actually book; your Nearest booking link works, so students who scan see your prices and request a time."], link: G("beauty-business-flyer", "How to make a flyer that converts") },
        { id: "nail-flyer", q: "What should a nail business flyer include?", a: ["Your business name, a crisp photo of your best set, three signature services with prices, your area, booking hours and a QR code to your booking page. If you serve students, say so and use your Nearest link for the QR code."], link: G("beauty-business-flyer", "Sample flyer copy") },
        { id: "lash-captions", q: "What captions should a lash technician use?", a: ["Name the set and the result: \"Classic set, 10–12 mm, natural cat-eye — refills Tue and Thu.\" Add aftercare tips, answer a common question, or tell a short story about the client's event, then one call to action — like your Nearest link for student bookings."], link: G("more-lash-clients-without-discounting", "Lash captions you can copy") },
        { id: "referral-promo", q: "How do I create a referral promotion for beauty services?", a: ["Reward both people with something small — a credit, a free add-on or priority booking — and set clear rules: new clients only, when it applies, and an end date. Share a link friends can book from directly, such as your Nearest profile link."], link: P("/beauty-marketing-resources#referral-scripts", "Referral promotion templates") },
        { id: "no-photos", q: "What should I post when I have no client photos?", a: ["Your process on practice heads or models, your workspace, tool cleaning, product explanations and your price list. Label practice work honestly. Nearest Model Calls are a quick way to get real client photos: post a discounted practice appointment and verified students can book a spot."], link: G("first-10-clients-new-hairstylist", "Building a portfolio") },
        { id: "openings-not-desperate", q: "How do I promote openings without looking desperate?", a: ["Present openings as information: \"Two spots Thursday after 4 for silk presses.\" Post on a regular rhythm, message your waitlist first, and keep prices steady. On Nearest, students simply see your open times — no announcement needed."], link: G("more-lash-clients-without-discounting", "Filling openings without discounting") },
        { id: "prom", q: "How do I market prom makeup or hair appointments?", a: ["Start four to eight weeks before local prom dates with looks for different outfits and skin tones, a clear package with timing and price, and trials. Be bookable where students are choosing: on Nearest, students compare event services by price and request a time; students under 18 need a parent's approval."], link: G("student-clients-prom-homecoming-graduation", "Prom, homecoming and graduation marketing") },
        { id: "back-to-school", q: "How do I market back-to-school grooming services?", a: ["Promote two to three weeks before classes start with fresh cuts, braids, nails and brows that hold up. Offer after-school and weekend slots and show low-maintenance styles. Students and parents search for these appointments — a Nearest profile with clear prices puts you in front of them."], link: G("student-clients-prom-homecoming-graduation", "Student seasons calendar") },
        { id: "homecoming", q: "What are effective homecoming beauty promotion ideas?", a: ["Bundle services friends can book together, post looks in school colors, offer group time slots, and share a simple timeline so students know when to book. On Nearest, add-ons let students build their own package on top of your base service."], link: G("student-clients-prom-homecoming-graduation", "Event-season promotion ideas") },
        { id: "graduation", q: "How do I plan graduation-season beauty promotions?", a: ["Announce availability a month ahead, offer photo-ready packages, and plan around ceremony times. Families often book several people, so offer back-to-back slots. Students looking for graduation appointments on Nearest see your prices and open times directly."], link: G("student-clients-prom-homecoming-graduation", "Graduation-season planning") },
        { id: "seasonal-budget", q: "How do I market seasonal services on a small budget?", a: ["Reuse one good photo shoot for weeks of posts, promote early, focus on a single seasonal offer, and partner with a local business. A free Nearest listing costs nothing to keep and is there whenever students start searching for event appointments."], link: G("get-more-beauty-clients-without-ads", "Low-budget growth") },
        { id: "insta-tiktok-google", q: "Should beauty professionals focus on Instagram, TikTok, or Google?", a: ["Go where clients are when they're ready to book. Google catches people searching right now; Instagram and TikTok show your work. If students are your clients, a Nearest profile is where they compare professionals and book. Most professionals do best with one social platform, a Google profile and one place to book."], link: G("get-beauty-business-found-on-google", "Getting found on Google") },
        { id: "bio", q: "How do I write a professional bio that gets bookings?", a: ["Say who you are, what you specialize in, who you love working with and how to book — in two or three sentences. Mention experience honestly and one detail that makes clients comfortable. Your Nearest profile has an About section for exactly this."], tips: ["Example: \"Hi, I'm Dani — I specialize in knotless braids and boho styles for school and events. I keep appointments on time and walk you through aftercare.\""], link: G("improve-beauty-profile-booking-conversion", "Profile and bio checklist") },
        { id: "marketing-plan", q: "How do I build a simple marketing plan for my beauty business?", a: ["Write down your ideal client, two or three services to promote, your channels, how often you'll post, and one number to track — new bookings per week. If students are your ideal client, make a free Nearest listing one of your channels. Review the plan monthly."], link: P("/grow-your-beauty-business", "Grow your beauty business") },
      ],
    },
    {
      slug: "pricing-operations", title: "Pricing, operations and growth", audience: "Beauty and wellness professionals",
      intro: "Pricing for students, profit per appointment, policies and growing at a pace you can keep.",
      items: [
        { id: "price-students", q: "How should I price beauty services for students?", a: ["Start from your real cost and time, then design student-friendly options — shorter services, simpler styles, off-peak times — instead of cutting your main price. On Nearest, every service is capped at the student price limit, so you design within a clear ceiling and set your own prices beneath it."], link: G("price-student-friendly-beauty-services", "Pricing student-friendly services profitably") },
        { id: "student-discount", q: "How do I offer student discounts without losing money?", a: ["Limit discounts to specific services or times you need to fill, set an end date or a cap, and check your profit per hour afterward. A dedicated student menu usually works better than a percentage off everything — and on Nearest that menu is what students see."], link: G("price-student-friendly-beauty-services", "Student pricing without losing money") },
        { id: "profit-per-appt", q: "How do I calculate profit per appointment?", a: [`Price, minus products, platform and card-processing fees, travel and a share of fixed costs, divided by total hours including setup and cleanup. On Nearest, the ${fee} booking fee is added to the student's total by default, so it doesn't reduce your price; card processing is deducted from your payout.`], link: G("price-student-friendly-beauty-services", "Profit-per-appointment worksheet") },
        { id: "duration", q: "How do I set service duration and availability?", a: ["Time yourself on real appointments, add buffer for consultation and cleanup, and round up. Set hours you can keep every week. On Nearest, each service's duration and your hours decide which times students can request, so accurate durations prevent overbooking."], link: G("improve-beauty-profile-booking-conversion", "Booking setup checklist") },
        { id: "which-promote", q: "How do I decide which services to promote first?", a: ["Promote services that earn the most per hour, that you enjoy, and that bring clients back. For student clients, lead with the services they book most often — cuts, braids, nails and lashes — at prices that fit a student budget. Those are the categories students browse most on Nearest."], link: G("price-student-friendly-beauty-services", "Choosing what to promote") },
        { id: "cancel-policy", q: "What is a good cancellation policy for beauty professionals?", a: ["Short, fair and enforced the same way for everyone: a deposit, a notice period, what happens to the deposit, and how lateness is handled. Nearest applies one policy to every booking: late cancellations and no-shows pay you the protected deposit, and the rest becomes the student's credit with you."], link: P("/faq#cancellations-refunds", "How Nearest's cancellation rules work") },
        { id: "more-profitable", q: "How do I make my beauty business more profitable?", a: ["Raise prices on in-demand services, add optional add-ons, reduce gaps between appointments, rebook before clients leave, and drop tools you don't use. A free listing with no monthly fee — like Nearest for new professionals — adds clients without adding a fixed cost."], link: G("price-student-friendly-beauty-services", "Profitability basics") },
        { id: "no-salon", q: "How do I grow without opening a salon?", a: ["Build your client base, raise prices as demand grows, add services that pair with yours, and consider a suite or mobile work before a salon. Nearest supports independent professionals working from a studio, a suite or by traveling to clients, with an optional travel fee."], link: P("/grow-your-beauty-business", "Growing as an independent professional") },
        { id: "platform-pros-cons", q: "What are the pros and cons of booking platforms?", a: ["Pros: online booking, deposits, reminders and payment handling, and sometimes new clients. Cons: fees, less control and another place to manage. Nearest is built to keep the cons small for new professionals — free to list, no monthly fee, works alongside your current tool — while bringing student clients you might not reach otherwise."], link: P("/free-business-listing", "How listing options compare") },
        { id: "choose-platform", q: "How do I choose a booking platform for my beauty business?", a: ["List what you need — deposits, reminders, client notes, payouts — and what you'll pay per month and per booking. Ask who your clients are there and whether it's active in your city. If students are part of your market, try Nearest alongside your current tool and count the bookings it brings."], tips: ["Ask: what does it cost per booking, how do refunds work, how fast are payouts?"], link: P("/free-business-listing", "Choosing where to list and book") },
        { id: "part-time", q: "Can I grow a beauty business part time?", a: ["Yes. Protect fixed days and hours, focus on two or three services, and let clients book without waiting for you to reply. On Nearest you set your own hours — including after-school-only hours — and go offline whenever you need to."], link: P("/grow-your-beauty-business", "Sustainable growth") },
        { id: "manageable-schedule", q: "How do I keep my schedule manageable while growing?", a: ["Cap appointments per day, build in breaks and buffer, block admin time weekly, and raise prices before adding hours. On Nearest, every booking starts as a request you accept or decline, so you stay in control of your calendar."], link: P("/grow-your-beauty-business", "Growing at a pace you can keep") },
        { id: "student-boundaries", q: "How can I serve students while maintaining professional boundaries?", a: ["Keep appointment communication in your booking tool, apply policies consistently, keep appointments to the service booked, and don't connect with young clients on personal social media. Nearest is built for this: messages stay in the app and phone numbers and emails aren't shared between students and professionals."], link: G("student-clients-prom-homecoming-graduation", "Serving student clients professionally") },
        { id: "minors-safety", q: "What safety practices matter when serving minors?", a: ["Follow your state's licensing rules and any parental-consent requirements for the service, keep communication in the booking platform, keep the door open or a parent welcome, and never offer services that require an adult client. This is general guidance, not legal advice."], tips: ["On Nearest, services marked 18+ only can't be booked by students under 18, and students 13–17 need a parent or guardian's approval to book."], link: P("/faq#safety-privacy", "How Nearest handles safety") },
      ],
    },
    {
      slug: "for-professionals", title: "Nearest for professionals", audience: "Professionals considering Nearest",
      intro: "How listing on Nearest works — written from the platform's current rules.",
      items: [
        { id: "what-is-nearest", q: "What is Nearest?", a: ["Nearest is the student beauty, wellness and self-care booking platform at usenearest.com. It connects high school, college, trade school and online students with independent beauty, grooming, wellness and self-care professionals near them. Students already get discounts on food, clothing, tech and entertainment; Nearest exists so self-care can be student-priced too. Bookings are available in cities where professionals are live."], link: P("/about-nearest", "About Nearest") },
        { id: "is-booking-platform", q: "Is Nearest a beauty booking platform?", a: ["Yes — a student-focused one. Students book and pay through Nearest; professionals set their own services, prices and hours. Nearest isn't a general directory for everyone: it serves verified students, and only in cities where it's live."], link: P("/for-professionals", "How Nearest works for professionals") },
        { id: "who-can-join", q: "Who can join Nearest as a professional?", a: ["Independent professionals who are at least 18, legally able to work in the U.S., and hold any license or permit their services require. You verify your identity with a government ID and a live selfie reviewed by Nearest, and you report your professional status yourself. Spots are limited per city and category."], link: P("/for-professionals", "Eligibility and how to join") },
        { id: "free-to-list", q: "Is it free to list my business on Nearest?", a: [`Yes for new professionals: no sign-up fee, no monthly membership fee and no card needed. Nearest earns a flat booking fee (currently ${fee}) on each service and Model Call booked; by default it's added to the student's total, so you receive your full price. Card-processing fees are deducted from each payout.`], link: P(ROUTES.proSignUp, "Join Nearest free") },
        { id: "monthly-fees", q: "Does Nearest charge professionals monthly fees?", a: [`New professionals pay no monthly membership fee. Nearest's revenue is the booking fee on each booking (currently ${fee}), added to the student's total by default. Professionals who joined under an earlier membership arrangement keep the terms of that arrangement; contact support with any questions about your account.`], link: P("/for-professionals#fees", "How Nearest earns") },
        { id: "replace-platform", q: "Does Nearest replace my current booking platform?", a: ["No. Nearest is designed to work alongside the tools you already use. Students who find you on Nearest book through Nearest; your other clients keep booking the way they do now. Block time across your calendars so you don't double-book."], link: P("/faq#nearest-alongside", "Using Nearest with another app") },
        { id: "how-register", q: "How do I register as a professional on Nearest?", a: ["Create an account at the professional sign-up page, then build your profile step by step: profile and photos, services and prices, professional status, location and travel, hours, communication, and identity verification. On the last step you read and accept the Professional Terms and submit for review."], link: P(ROUTES.proSignUp, "Join as a professional") },
        { id: "help-create-profile", q: "Can Nearest help create my professional profile with permission?", a: ["Yes. With your permission, someone on the Nearest team can set up your profile from details you share. You receive an email link, create your own password, review your profile and accept the Professional Terms before it goes live. After that, it's your account."], link: P("/for-professionals#profile-help", "Profile setup help") },
        { id: "services-list", q: "What services can professionals list on Nearest?", a: [`Categories currently include ${f.categories.join(", ")}. Within each category you list your own services, prices, durations and optional add-ons. Services that legally require an adult client can be marked 18+ only.`], link: P("/for-professionals#services", "Service categories") },
        { id: "student-pricing-required", q: "Do professionals need to offer student-friendly pricing?", a: [`Yes — Nearest is a student platform, so no service can cost students more than ${cap}, including add-ons. Within that limit you set your own prices. Travel fees are separate when you go to the student.`], link: G("price-student-friendly-beauty-services", "Pricing student-friendly services") },
        { id: "price-limits", q: "Are there price limits for certain services?", a: [`Yes. On Nearest the current limit is ${cap} per service, add-ons included, and it applies to every category. A travel fee is added only when you travel. Any category-specific limit would be shown in the app when you set prices.`], link: P("/for-professionals#fees", "Pricing rules") },
        { id: "city-capacity", q: "How does city enrollment capacity work?", a: [`It's the same in every city and state: each service category opens with ${f.firstInPerCategory} professional spots. When they're taken, enrollment closes for that category in that city. Nearest may authorize one more opening of ${f.capPerCategory - f.firstInPerCategory} later — never more than ${f.capPerCategory} professionals per category per city.`], link: P("/for-professionals#capacity", "Capacity, explained") },
        { id: "city-full", q: "What if enrollment in my city is full?", a: ["Join the waitlist for your city and category. Enrollment doesn't reopen automatically; if Nearest authorizes the additional opening, or a spot is released, people on the waitlist are told first. A reopening isn't guaranteed."], link: P("/for-professionals#capacity", "Capacity and the waitlist") },
        { id: "which-cities", q: "What cities or states currently have Nearest?", a: ["Nearest is building nationwide, city by city. A city is live for student bookings once professionals there are approved and live. The Locations page lists those cities from the platform, and its city checker shows whether a city is live, open for professionals, closed in a category, or not open yet."], link: P("/locations", "Check a city") },
        { id: "join-before-launch", q: "Can I join before Nearest launches in my city?", a: ["Yes, wherever Nearest has opened professional enrollment for your city — you can build your profile and go live there before students start booking. If your city isn't open yet, leave your details with the city checker and Nearest can contact you when it opens. Being able to join doesn't mean students are already booking there."], link: P("/locations#check", "Check your city") },
        { id: "guarantee", q: "Does listing guarantee clients or bookings?", a: ["No. Nearest gives you a place to be discovered by verified students in your city. Bookings depend on demand, your profile, prices and availability. Nearest doesn't promise bookings, income or search placement."], link: G("improve-beauty-profile-booking-conversion", "Improve your booking conversion") },
        { id: "approvals", q: "How do appointment approvals work?", a: [`Every Nearest booking starts as a request. You get a notification, an email and — if you turn them on — phone alerts. You accept or decline within ${f.requestHours} hours (or by 2 hours before the start). After you accept, the student pays to confirm.`], link: P("/for-professionals#how-booking-works", "How booking works") },
        { id: "payments-pros", q: "How do professionals receive payments?", a: ["Payouts go through Stripe Connect to the account you connect. The student pays in full when they confirm; Nearest's processor holds it and releases it to you when the appointment is finished. Card-processing fees are deducted from payouts."], link: P("/for-professionals#fees", "Payouts and fees") },
        { id: "insurance", q: "Are there professional insurance options?", a: ["Nearest's Terms require professionals to carry professional liability and general liability insurance appropriate to their services. Nearest doesn't sell insurance; it's exploring options with a future licensed partner and asks professionals about their interest."], link: P(ROUTES.terms, "Read the Terms") },
        { id: "credentials", q: "What credentials or training status can professionals indicate?", a: ["Professionals choose one status: licensed, license pending, currently enrolled, or self-taught. It's self-reported — Nearest doesn't verify licenses — and each professional is responsible for holding every license their services require."], link: P("/for-professionals#eligibility", "Eligibility") },
        { id: "school-property", q: "Can professionals serve students without going onto school property?", a: ["Yes — that's how Nearest works. Appointments happen at the professional's location or at an address the student provides. Nearest doesn't schedule services at schools and has no school partnerships or access to school property."], link: P("/faq#safety-privacy", "Safety and privacy") },
        { id: "safety-privacy", q: "How does Nearest protect privacy and safety?", a: [`Students are verified, professionals' identities are checked, phone numbers and emails aren't shared between users, messages stay in the app, and appointment addresses are shared only from 12:00 AM on the appointment day. Check-in requires being within ${f.checkinFeet} feet.`], link: P(ROUTES.privacy, "Privacy Policy") },
        { id: "contact-support", q: "How do I contact Nearest support?", a: [`Email ${SUPPORT_EMAIL}. Signed-in users can also report a problem from inside the app.`], link: P("/contact", "Contact Nearest") },
        { id: "update-profile", q: "How do I update my Nearest profile?", a: ["Sign in, open Business, and edit any step — photos, services, prices, location, hours and more. You can also go offline from Today whenever you need a break."], link: P(ROUTES.proSignIn, "Professional sign in") },
      ],
    },
    {
      slug: "students-parents", title: "Students and parents", audience: "Students and their families",
      intro: "How students find professionals, book, pay and stay safe on Nearest.",
      items: [
        { id: "affordable-students", q: "How can students find affordable beauty services?", a: [`Compare prices before you book, ask about simpler versions of styles, book off-peak times, and look for practice appointments with clear expectations. Nearest is built for this: every service is capped at ${cap}, professionals post student-friendly menus and Model Calls, and the total you see already includes the ${fee} booking fee.`], link: G("save-on-beauty-and-grooming-as-a-student", "How students can save on beauty and grooming") },
        { id: "prom-book", q: "Where can students book prom hair and makeup?", a: ["Book early — four to six weeks ahead — with someone whose past event work you like. Ask about a trial, timing on the day, and what's included. On Nearest, verified students in live cities can browse professionals, see prices and request a time."], link: G("prom-homecoming-beauty-budget", "Prom and homecoming budget planner") },
        { id: "affordable-nails", q: "How can students find affordable nail appointments?", a: ["Choose shorter lengths or simpler designs, compare prices for the same set, and book weekday or after-school times. On Nearest you can compare nail techs in your city side by side, see photos of their sets and the full price before you request."], link: G("save-on-beauty-and-grooming-as-a-student", "Ways to save as a student") },
        { id: "haircuts", q: "Where can students book haircuts or barber services?", a: ["Look for a barber or stylist whose recent cuts match what you want, with clear prices and times that fit your schedule. On Nearest, the Barber and Hair categories show professionals live in your area."], link: G("student-grooming-on-a-budget", "Student grooming on a budget") },
        { id: "graduation-book", q: "How do students find graduation beauty appointments?", a: ["Graduation week fills fast, so book a month ahead, confirm timing around your ceremony and photos, and ask if family or friends can book back-to-back. On Nearest you can request a time with professionals live in your city and see their open dates before graduation week."], link: G("prom-homecoming-beauty-budget", "Event beauty on a budget") },
        { id: "services-available", q: "What services are available on Nearest?", a: [`Professionals list services in categories including ${f.categories.slice(0, 10).join(", ")} and more. What's available depends on which professionals are live in your city.`], link: P("/locations", "See what's live near you") },
        { id: "create-account", q: "How do students create a Nearest account?", a: ["Sign up, then verify you're a current student with a school ID photo and a selfie, proof of enrollment if your school doesn't issue IDs, or a code sent to your school email. Students 13–17 also need a parent or guardian to approve from an email Nearest sends them."], link: P(ROUTES.studentSignUp, "Create a student account") },
        { id: "how-booking", q: "How does booking on Nearest work?", a: [`Pick a professional, service and time, and send a request — you aren't charged yet. The professional accepts (or declines). Once accepted, you pay within ${f.payHours} hours to confirm. Standard bookings must be at least ${f.advanceHours} hours ahead; same-day bookings are possible only for posted openings.`], link: P("/student-beauty-services#how-booking-works", "Booking, step by step") },
        { id: "student-pricing-how", q: "How does student-friendly pricing work?", a: [`Professionals set their own prices, and no service on Nearest can cost more than ${cap}, including add-ons. Some professionals also post Model Calls — discounted appointments where they practice a technique or build a portfolio.`], link: P("/student-beauty-services", "Student-friendly pricing") },
        { id: "booking-fee", q: "Does Nearest charge students a booking fee?", a: [`Yes — a ${fee} booking fee per service. It's included in the total you see before you pay, so there's no surprise charge at checkout.`], link: P(ROUTES.terms, "Payments in the Terms") },
        { id: "when-pay", q: "When do students pay for appointments?", a: [`After the professional accepts your Nearest request. You then have ${f.payHours} hours (or until 1 hour before the start) to pay in full. Your payment is held until you complete the appointment's finish steps, then released to the professional.`], link: P("/student-beauty-services#how-booking-works", "Payment timing") },
        { id: "see-nearby", q: "How can students see available professionals near them?", a: ["After you sign in, Explore shows professionals live in your area, with filters for service and price. You can also search a ZIP code or nearby city."], link: P("/locations", "Cities where Nearest is live") },
        { id: "in-my-city", q: "Is Nearest available in my city?", a: ["Use the city checker on the Locations page. It shows whether students can book there now. If not, you can ask to be told when it opens — Nearest is growing nationwide, but only cities with live professionals have bookable appointments."], link: P("/locations#check", "Check your city") },
        { id: "parents-help", q: "Can parents or guardians help with booking?", a: ["Yes. Students book from their own verified Nearest account, and for students 13–17 a parent or guardian must approve the account from an email before the student can book. Parents are responsible for payments on a minor's account."], link: G("parents-guide-teen-beauty-appointments", "A parent's guide to teen appointments") },
        { id: "declined", q: "What happens if a professional declines a booking?", a: ["Nearest tells you right away and you aren't charged, because you haven't paid yet. Pick another time or professional. If nobody answers in time, the request expires the same way, with no charge."], link: P("/student-beauty-services#how-booking-works", "How requests work") },
        { id: "addresses-safety", q: "How are appointments and addresses handled safely?", a: [`The appointment address is shared only with the booked student (or, for travel appointments, the professional) starting at 12:00 AM Central Time on the appointment day. Messages stay in the Nearest app. At the appointment, you check in within ${f.checkinFeet} feet.`], link: P("/faq#safety-privacy", "Safety and privacy") },
        { id: "before-appt", q: "What should students do before an appointment?", a: ["Read the service details and any preparation notes, tell your professional about allergies or sensitivities, plan to arrive on time, and keep messages in the Nearest app. You'll see the address from 12:00 AM on the appointment day and check in when you arrive."], link: P("/student-beauty-services", "Appointment tips") },
        { id: "cancellations-refunds", q: "How do refunds or cancellations work?", a: [`Nearest uses credits instead of cash refunds. Cancel ${f.cancelHours} hours or more ahead and the full amount becomes credit with that professional. Cancel later, or miss the appointment, and the ${usd(f.depositDollars)} protected deposit goes to the professional while the rest becomes credit. If a professional cancels, you get the full amount as general credit.`], link: P(ROUTES.terms, "Section 7 of the Terms") },
        { id: "school-affiliation", q: "Is Nearest affiliated with a school or school district?", a: ["No. Nearest is an independent company. It verifies that users are students, but it isn't affiliated with, endorsed by or partnered with any school or school district."], link: P("/about-nearest", "About Nearest") },
        { id: "none-nearby", q: "What if no professionals are listed nearby?", a: ["Nearest may not be live in your area yet. Try a nearby city or ZIP code, or use the city checker to ask to be told when it opens. If you know a great local professional, tell them about the professional sign-up — every city needs its first five."], link: P("/locations#check", "Check your city") },
      ],
    },
    {
      slug: "about-the-brand", title: "About Nearest and comparisons", audience: "Everyone",
      intro: "What Nearest is, how to find the official site, and how it compares with other options.",
      items: [
        { id: "student-app", q: "What is the Nearest student booking app?", a: ["It's the student side of Nearest: an installable web app at usenearest.com where verified students find independent beauty and wellness professionals near them and request, pay for and complete appointments. It installs from the browser — no app store needed."], link: P("/student-beauty-services", "Nearest for students") },
        { id: "usenearest", q: "What is usenearest.com?", a: ["usenearest.com is the official website and web app of Nearest, the student beauty, wellness and self-care booking platform. Students and professionals sign in there, and this resource center lives there too."], link: P("/about-nearest", "About Nearest") },
        { id: "official-site", q: "How do I find the official Nearest website?", a: ["Go to https://www.usenearest.com. When searching, look for \"Nearest beauty booking\" or \"usenearest\" — the word \"nearest\" on its own returns unrelated results. Nearest's official Instagram is @usenearest."], link: P("/about-nearest", "Official details") },
        { id: "students-or-pros", q: "Is Nearest for students or beauty professionals?", a: ["Both. Verified students book appointments; independent professionals list their services to reach those students. Each has its own sign-up: students at usenearest.com, professionals at usenearest.com/pro."], link: P("/for-professionals", "For professionals") },
        { id: "vs-directory", q: "What makes Nearest different from a general beauty directory?", a: [`A general directory lists everyone for everyone. Nearest is built for one audience — verified students — with prices capped at ${cap}, booking and payment inside the app, verified identities, safety rules around addresses and messages, and a limited number of professionals per category in each city.`], link: P("/free-business-listing", "How listing options compare") },
        { id: "nearest-alongside", q: "Can Nearest be used alongside another booking app?", a: ["Yes. Nearest doesn't require you to leave your current booking platform. Keep your calendars in sync by blocking time when a booking comes in from any source."], link: P("/for-professionals", "Nearest for professionals") },
        { id: "help-independent", q: "How does Nearest help independent beauty professionals?", a: ["It gives independent professionals a free place to be found by verified students in their city, with requests, payments, reminders and appointment-day tools handled in one app. It's a discovery channel, not a guarantee of bookings."], link: P("/for-professionals", "How it works") },
        { id: "any-state", q: "Can professionals from any US state apply to join Nearest?", a: ["Yes. Professionals anywhere in the U.S. can register their interest, and can enroll wherever Nearest has opened their city. Each city opens every service category with a limited number of spots, so availability depends on your city and service — not your state."], link: P("/for-professionals", "How joining works") },
        { id: "accepting-my-city", q: "How do I find out whether Nearest is accepting professionals in my city?", a: ["Search your city or ZIP code in the city checker on the Locations page. It tells you whether enrollment is open in your city and category, closed because the spots are taken, or not open yet — and lets you leave your details so Nearest can contact you if that changes."], link: P("/locations#check", "Check your city") },
        { id: "free-vs-paid", q: "What is the difference between a free listing and a paid advertisement?", a: ["A free listing is a profile people can find when they browse or search; a paid advertisement buys extra placement for a set time and stops when you stop paying. Listings build lasting visibility. A Nearest listing is free for new professionals and puts you in front of verified students in your city without an ad budget."], link: P("/free-business-listing", "Free listings vs ads") },
        { id: "right-platform", q: "How do I know whether a beauty platform is right for my business?", a: ["Check who uses it, whether it's active in your area, what it costs per month and per booking, how payouts and refunds work, and whether it fits your services. If students are part of your market, Nearest is worth testing: it's free for new professionals, works alongside your current tool, and you can count the bookings it brings."], link: P("/locations#check", "Check whether your city is open") },
        { id: "get-started", q: "How can I get started with Nearest today?", a: ["Professionals: check your city on the Locations page, then create an account at the professional sign-up and build your profile — or leave your details if your city isn't open yet. Students: create an account at usenearest.com and verify you're a student."], link: P(ROUTES.proSignUp, "Join as a professional") },
      ],
    },
  ];
}
